fmtp<-function(x){raw<-as.character(x);z<-suppressWarnings(as.numeric(raw));ifelse(is.na(raw),"NR",ifelse(grepl("^<",raw),chartr(".",",",raw),ifelse(z<.001,"<0,001",sub("\\.",",",sprintf("%.3f",z)))))}
fmtor<-function(x)sub("\\.",",",sprintf("%.2f",x)); interval<-function(a,b)paste0(fmtor(a),"–",fmtor(b))
