t9<-bind_rows(
 sp%>%filter(Variable %in% c("Acompañada vs sola","Controles prenatales, por 1 DE adicional","Sesiones de psicoprofilaxis, por 1 DE adicional","Eclampsia vs ningún trastorno hipertensivo"))%>%transmute(Análisis=paste("Prior",Modelo),Factor=Variable,OR=fmtor(OR_posterior),CrI95=interval(CrI95_inf,CrI95_sup),P_dirección=fmtp(ifelse(OR_posterior>=1,P_OR_mayor_1,P_OR_menor_1))),
 seg%>%filter(Variable %in% c("Acompañada vs sola","Controles prenatales, por 1 DE adicional","Sesiones de psicoprofilaxis, por 1 DE adicional","Edad gestacional, por 1 DE adicional"))%>%transmute(Análisis="Ajustado por edad gestacional",Factor=Variable,OR=fmtor(OR_posterior),CrI95=interval(CrI95_inf,CrI95_sup),P_dirección=fmtp(ifelse(OR_posterior>=1,P_OR_mayor_1,P_OR_menor_1))),
 sh%>%filter(Variable=="Preeclampsia/eclampsia vs ninguno")%>%transmute(Análisis="Hipertensión agrupada",Factor=Variable,OR=fmtor(OR_posterior),CrI95=interval(CrI95_inf,CrI95_sup),P_dirección=fmtp(P_OR_mayor_1)),
 ss%>%filter(Variable=="Seguro sí vs no")%>%transmute(Análisis="Seguro, casos completos",Factor=Variable,OR=fmtor(OR_posterior),CrI95=interval(CrI95_inf,CrI95_sup),P_dirección=fmtp(P_OR_mayor_1)),
 sa%>%filter(Variable %in% c("Familiar vs pareja","Otro vs pareja","Sola vs pareja"))%>%transmute(Análisis="Acompañamiento detallado",Factor=Variable,OR=fmtor(OR_posterior),CrI95=interval(CrI95_inf,CrI95_sup),P_dirección=fmtp(ifelse(OR_posterior>=1,P_OR_mayor_1,P_OR_menor_1))))
