estilizar_referencia<-function(path){td<-tempfile("docx_style_");dir.create(td);utils::unzip(path,exdir=td);sf<-file.path(td,"word","styles.xml");x<-paste(readLines(sf,warn=FALSE),collapse="");x<-gsub('<w:rFonts[^>]*/>','<w:rFonts w:ascii="Times New Roman" w:hAnsi="Times New Roman" w:eastAsia="Times New Roman" w:cs="Times New Roman"/>',x);x<-gsub('<w:pPrDefault\\s*/>','<w:pPrDefault><w:pPr><w:spacing w:line="360" w:lineRule="auto"/></w:pPr></w:pPrDefault>',x);writeLines(x,sf,useBytes=TRUE);old<-getwd();setwd(td);on.exit(setwd(old),add=TRUE);unlink(path);zip::zipr(path,list.files(".",all.files=TRUE,no..=TRUE),include_directories=TRUE);invisible(path)}
estilizar_referencia(refpath)
